tariff "t"
input rate: Money/mi = $2.35/mi
input flatRate: Money = $900
let linehaul = best "Linehaul" {
  option "Per mile" { charge "Linehaul" (quantity: shipment.distance, rate: rate) }
  option "Flat" { charge "Flat rate" = flatRate }
}
charge "Fuel surcharge" as FSC = linehaul * 32%

tariff "t"
let x = best "L" {
  option "A" { fail "A is out" }
  option "B" { require false else "B is out" }
}
charge "x" = x

tariff "t"
var fees = $0
for stop in shipment.stops {
  fees += worst "Stop" {
    option "Flat" { charge "Stop {stop.sequence} flat" = $10 }
    option "Per stop" { charge "Stop {stop.sequence}" = $4 * stop.sequence }
  }
}
note "{fees}"

tariff "t"
charge "Base" = $100
best "L" {
  option "A" {
    charge "A" = $10
    note "A sees {bill.total}"
  }
  option "B" {
    charge "B" = $20
    charge "B2" = bill.total * 10%
    note "B sees {bill.total}"
  }
}
note "after {bill.total}"

tariff "t"
charge "Base" = $100
best "Outer" {
  option "O1" {
    charge "O1" = $5
    best "Inner" {
      option "I1" { charge "I1" = bill.total }
      option "I2" { charge "I2" = $200 }
    }
  }
  option "O2" { charge "O2" = $1_000 }
}
